class EnhancedSession:
    @staticmethod
    def create_session_with_retry(proxies=None):
        session = requests.Session()
        retry_strategy = Retry(
            total=5,
            backoff_factor=2,
            status_forcelist=[429, 500, 502, 503, 504],
            allowed_methods=["HEAD", "GET", "OPTIONS", "POST"]
        )

        adapter = HTTPAdapter(max_retries=retry_strategy)
        session.mount("http://", adapter)
        session.mount("https://", adapter)

        if proxies:
            session.proxies.update(proxies)

        session.timeout = 10

        return session

class TorManager:
    def __init__(self):
        self.tor_configs = [
            {'proxy_port': 9050},
            {'proxy_port': 9051},
            {'proxy_port': 9052},
            {'proxy_port': 9053},
            {'proxy_port': 10050},
            {'proxy_port': 10051},
            {'proxy_port': 10052},
            {'proxy_port': 10053},        
        ]
        self.current_sessions = {'direct': None, 'tor': None}

    def get_sessions(self, iteration):
        direct_session = EnhancedSession.create_session_with_retry()
        cycle_position = random.randint(0, 7)  # 0-7 cho 8 configs
        config = self.tor_configs[cycle_position]

        tor_proxies = {
            'http': f'socks5://127.0.0.1:{config["proxy_port"]}',
            'https': f'socks5://127.0.0.1:{config["proxy_port"]}'
        }

        tor_session = EnhancedSession.create_session_with_retry(tor_proxies)

        print(f"[LẦN {iteration}] Chạy song song: Direct + Tor cổng {config['proxy_port']}")

        self.current_sessions = {
            'direct': direct_session,
            'tor': tor_session
        }

        return direct_session, tor_session    

tor_manager = TorManager()

def dual_request_race(method, url, session_direct, session_tor, **kwargs):
    ua = UserAgent()  # Khởi tạo UserAgent

    def make_request_enhanced(session, conn_type, max_retries=2):
        for attempt in range(max_retries):
            try:
                start_time = time.time()

                local_kwargs = kwargs.copy()
                headers = local_kwargs.get('headers', {})
                if 'User-Agent' not in headers and 'user-agent' not in headers:
                    headers['User-Agent'] = ua.random
                elif 'user-agent' in headers:
                    headers['User-Agent'] = headers.pop('user-agent')

                local_kwargs['headers'] = headers
                
                timeout = local_kwargs.get('timeout', 8) + attempt
                local_kwargs['timeout'] = timeout
                if attempt > 0:
                    time.sleep(random.uniform(0.5, 1.5))
                method_lower = method.lower()
                if method_lower == 'get':
                    response = session.get(url, **local_kwargs)
                elif method_lower == 'post':
                    response = session.post(url, **local_kwargs)
                elif method_lower == 'put':
                    response = session.put(url, **local_kwargs)
                elif method_lower == 'delete':
                    response = session.delete(url, **local_kwargs)
                else:
                    response = session.request(method, url, **local_kwargs)

                elapsed = time.time() - start_time
                if response.status_code in [200, 201, 202, 302]:
                    if attempt > 0:
                        print(f"  ✓ {conn_type} OK sau {attempt+1} lần thử ({elapsed:.2f}s)")
                    return response, conn_type, None
                elif attempt == max_retries - 1:
                    return None, conn_type, f"Status {response.status_code}"

            except Exception as e:
                if attempt == max_retries - 1:
                    return None, conn_type, str(e)[:50]

        return None, conn_type, "All retries failed"

    with ThreadPoolExecutor(max_workers=2) as executor:
        future_direct = executor.submit(make_request_enhanced, session_direct, "direct")
        future_tor = executor.submit(make_request_enhanced, session_tor, "tor")

        for future in as_completed([future_direct, future_tor]):
            response, conn_type, error = future.result()
            if response is not None:
                for f in [future_direct, future_tor]:
                    if f != future:
                        f.cancel()
                return response

    errors = [future_direct.result()[2], future_tor.result()[2]]
    raise Exception(f"Both enhanced requests failed. Errors: {errors}")

def auto_inject_dual_session(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        direct_session = tor_manager.current_sessions['direct']
        tor_session = tor_manager.current_sessions['tor']

        if not direct_session or not tor_session:
            return func(*args, **kwargs)

        old_get = requests.get
        old_post = requests.post
        old_put = requests.put
        old_delete = requests.delete
        old_request = requests.request

        def race_get(url, **req_kwargs):
            return dual_request_race('GET', url, direct_session, tor_session, **req_kwargs)

        def race_post(url, **req_kwargs):
            return dual_request_race('POST', url, direct_session, tor_session, **req_kwargs)

        def race_put(url, **req_kwargs):
            return dual_request_race('PUT', url, direct_session, tor_session, **req_kwargs)

        def race_delete(url, **req_kwargs):
            return dual_request_race('DELETE', url, direct_session, tor_session, **req_kwargs)

        def race_request(method, url, **req_kwargs):
            return dual_request_race(method, url, direct_session, tor_session, **req_kwargs)

        requests.get = race_get
        requests.post = race_post
        requests.put = race_put
        requests.delete = race_delete
        requests.request = race_request

        try:
            result = func(*args, **kwargs)
        finally:
            requests.get = old_get
            requests.post = old_post
            requests.put = old_put
            requests.delete = old_delete
            requests.request = old_request

        return result

    return wrapper

